"use client";

import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";

import { Canvas, useFrame, useThree } from "@react-three/fiber";
import * as THREE from "three";

import {
  setupOutlinePipeline,
  applyOutlineConfig,
  renderOutlineFrame,
  resizeOutlinePipeline,
  type PromoOutlineConfig,
} from "../postfx/promoOutline";

import {
  applyEmoteToRig,
  buildBoneTree,
  createSteveRig,
  loadSkinTexture,
  mountCosmeticOnRig,
  steveGeoForVariant,
  RIG_RENDERER_SETTINGS,
  EmotePlayer,
  STEVE_HEIGHT_PX,
  STEVE_WORLD_SCALE,
  PARTICLE_WORLD_SCALE,
  ParticleSystem,
  EmoteParticles,
  EmoteSounds,
  inferModelVariant,
  createNametag,
  CAMERA_FOV,
  CAMERA_POSITION,
  DEFAULT_NAMETAG_FONT,
  DOWN_SHIFT,
  LIGHTING,
  NAMETAG_HAT_EXTRA_Y,
  NAMETAG_LAYER,
  NAMETAG_PX_Y,
  POSE_ROTATION_Y,
  STEVE_CENTER_PX,
  type BoneTree,
  type SteveRig,
  type CosmeticAssetUrls,
  type EmoteAssetUrls,
  type EmoteSoundsOptions,
  type EmitterHandle,
  type NametagOptions,
  type SteveModelVariant,
  getWebGLSupport,
  RIG_CONTEXT_ATTRIBUTES,
  type WebGLSupport,
} from "../core";
import { CosmeticGeoModel } from "./CosmeticGeoModel";
import { FlatSkin } from "./FlatSkin";
import { OverlayCosmetic } from "./OverlayCosmetic";
import { useCosmeticGeo } from "./useCosmeticGeo";
import { useEmote } from "./useEmote";
import { BipedBones } from "../core/boneNames";

const DRAG_SENSITIVITY = 0.012;
const MAX_PITCH = Math.PI / 3;

interface DragState {
  yaw: number;
  pitch: number;
}
const SKELETON_FADE_S = 0.4;
const DEFAULT_SKELETON_COLOR = "#a78bfa";

export interface SkinRendererCosmetic {
  id: string;
  type?: string;
  urls: CosmeticAssetUrls;
}

export type SkinRendererNametag = NametagOptions;

export interface SkinRendererCape {
  texture: string;
  mcmeta?: string;
  mcmetaJson?: unknown;
  elytra?: boolean;
}

export interface SkinRendererProps {
  textureUrl: string | null;
  emoteSounds?: EmoteSoundsOptions | null;
  /** `"auto"` reads the arm width out of the texture; nothing in a skin file states the model. */
  variant?: SteveModelVariant | "auto";
  cosmetics?: SkinRendererCosmetic[];
  cape?: string | SkinRendererCape | null;
  emote?: EmoteAssetUrls | null;
  emoteLoop?: boolean;
  onEmoteEnd?: () => void;
  nametag?: SkinRendererNametag | null;
  outline?: boolean | Partial<PromoOutlineConfig>;
  spinSpeed?: number;
  rotation?: number;
  zoom?: number;
  draggable?: boolean;
  /** `"yaw"` keeps the drag horizontal; `"both"` also lets the rig tilt. */
  dragAxis?: "yaw" | "both";
  loading?: boolean;
  paused?: boolean;
  fps?: number | null;
  maxDpr?: number;
  dpr?: number;
  skeletonColor?: string;
  className?: string;
  style?: React.CSSProperties;
  unsupportedFallback?: ReactNode;
  onUnsupported?: (support: WebGLSupport) => void;
}

function Nametag({
  tag,
  y,
}: {
  tag: SkinRendererNametag;
  y: number;
}) {
  const handle = useMemo(
    () =>
      createNametag({
        text: tag.text,
        iconUrl: tag.iconUrl ?? null,
        iconPlus: tag.iconPlus ?? false,
        font: tag.font ?? DEFAULT_NAMETAG_FONT,
      }),
    [tag.text, tag.iconUrl, tag.iconPlus, tag.font]
  );
  useEffect(() => () => handle.dispose(), [handle]);
  return <primitive object={handle.mesh} position={[0, y, 0]} />;
}

function EmoteDriver({
  tree,
  urls,
  loop,
  onEnd,
  sounds,
}: {
  tree: BoneTree;
  urls: EmoteAssetUrls;
  loop?: boolean;
  onEnd?: () => void;
  sounds?: EmoteSoundsOptions | null;
}) {
  const state = useEmote(urls, { negateX: true });
  const playerRef = useRef<EmotePlayer | null>(null);
  const startedRef = useRef(false);
  const onEndRef = useRef(onEnd);
  onEndRef.current = onEnd;

  const particles = useMemo(() => {
    if (state.status !== "ready" || state.data.particleEffects.size === 0) return null;
    return new EmoteParticles({
      effects: state.data.particleEffects,
      rig: tree,
      prop: state.data.prop?.tree,
      unitScale: PARTICLE_WORLD_SCALE,
    });
  }, [state, tree]);

  useEffect(() => () => particles?.dispose(), [particles]);

  const audio = useMemo(() => (sounds ? new EmoteSounds(sounds) : null), [sounds]);
  useEffect(() => () => audio?.dispose(), [audio]);

  useEffect(() => {
    if (state.status === "ready") {
      const emoteId = state.data.emote.id;
      const p = new EmotePlayer({
        keyframeListener: {
          onParticleKeyframe: (_id, _time, keyframe) => particles?.spawn(keyframe),
          onSoundKeyframe: (_id, _time, keyframe) => audio?.play(keyframe),
          onEmoteFinished: (id) => {
            if (id === emoteId) onEndRef.current?.();
          },
        },
      });
      playerRef.current = p;
      startedRef.current = false;
    }
    return () => {
      playerRef.current = null;
    };
  }, [state, loop, particles, audio]);

  useFrame((st, delta) => {
    if (state.status !== "ready" || !playerRef.current) return;
    const player = playerRef.current;
    const t = st.clock.elapsedTime;
    if (!startedRef.current) {
      player.play(state.data.emote, t, { loop });
      startedRef.current = true;
    } else if (loop !== false && !player.isPlaying(state.data.emote.id)) {
      player.play(state.data.emote, t, { loop });
    }
    player.update(t);
    applyEmoteToRig(player, tree, {
      negateX: true,
      propTree: state.data.prop?.tree,
    });
    particles?.tick(t, delta);
  });

  if (state.status !== "ready") return null;
  return (
    <>
      {state.data.prop && <primitive object={state.data.prop.tree.root} />}
      {particles && <primitive object={particles.root} />}
    </>
  );
}

function SteveBody({
  steve,
  textureUrl,
  emoteUrls,
  emoteLoop,
  onEmoteEnd,
  emoteSounds,
}: {
  steve: SteveRig;
  textureUrl: string | null;
  emoteUrls?: EmoteAssetUrls | null;
  emoteLoop?: boolean;
  onEmoteEnd?: () => void;
  emoteSounds?: EmoteSoundsOptions | null;
}) {
  useEffect(() => {
    if (!textureUrl) return;
    let alive = true;
    let loaded: THREE.Texture | null = null;

    loadSkinTexture(textureUrl).then((texture) => {
      if (!alive) {
        texture.dispose();
        return;
      }
      loaded = texture;
      steve.material.map?.dispose();
      steve.material.map = texture;
      steve.material.needsUpdate = true;
    }, () => undefined);

    return () => {
      alive = false;
      if (loaded && steve.material.map === loaded) {
        steve.material.map = null;
        steve.material.needsUpdate = true;
      }
      loaded?.dispose();
    };
  }, [steve, textureUrl]);

  return (
    <>
      <primitive object={steve.tree.root} />
      {emoteUrls && (
        <EmoteDriver
          tree={steve.tree}
          urls={emoteUrls}
          loop={emoteLoop}
          onEnd={onEmoteEnd}
          sounds={emoteSounds}
        />
      )}
    </>
  );
}

function MountedCosmetic({
  cosmetic,
  anchorRef,
  steve,
  variant,
}: {
  cosmetic: SkinRendererCosmetic;
  anchorRef: React.RefObject<THREE.Group>;
  steve: SteveRig;
  variant: SteveModelVariant;
}) {
  const state = useCosmeticGeo(cosmetic.urls);
  const sysRef = useRef<ParticleSystem | null>(null);

  useEffect(() => {
    if (state.status !== "ready") return;
    return mountCosmeticOnRig(state.data, steve, variant);
  }, [state, steve, variant]);

  useEffect(() => {
    if (state.status !== "ready") return;
    const anchor = anchorRef.current;
    const data = state.data;
    if (!anchor || data.particleEffects.length === 0) return;

    const sys = new ParticleSystem();
    for (const pe of data.particleEffects) {
      sys.register(pe.loaded.effect.identifier, pe.loaded);
    }
    const tmp = new THREE.Vector3();
    const handles: EmitterHandle[] = [];
    for (const pe of data.particleEffects) {
      const name = pe.entry.anchor;
      const own = name
        ? data.tree.bones.get(name) ?? data.tree.locators.get(name)
        : undefined;
      handles.push(
        sys.spawn(pe.loaded.effect.identifier, {
          positionProvider: () => {
            const target =
              own && isAttachedTo(own, steve.tree.root)
                ? own
                : steve.tree.bones.get(BipedBones.BODY) ?? data.tree.root;
            return target.getWorldPosition(tmp).clone();
          },
          forceLifetime: "looping",
          unitScale: PARTICLE_WORLD_SCALE,
        })
      );
    }
    anchor.add(sys.root);
    sysRef.current = sys;
    return () => {
      for (const h of handles) h.stop();
      anchor.remove(sys.root);
      sys.dispose();
      sysRef.current = null;
    };
  }, [state, anchorRef]);

  useFrame((st, delta) => {
    sysRef.current?.tick(st.clock.elapsedTime, delta);
  });

  if (state.status !== "ready") return null;
  if (!state.data.hasArmorBones && state.data.particleEffects.length === 0) {
    return null;
  }
  return <CosmeticGeoModel cosmetic={state.data} />;
}

function RigContent({
  textureUrl,
  variant,
  cosmetics,
  emote,
  emoteLoop,
  onEmoteEnd,
  emoteSounds,
  spinSpeed,
  rotation,
  dragRef,
  nametag,
}: {
  textureUrl: string | null;
  variant: SteveModelVariant;
  cosmetics: SkinRendererCosmetic[];
  emote?: EmoteAssetUrls | null;
  emoteLoop?: boolean;
  onEmoteEnd?: () => void;
  emoteSounds?: EmoteSoundsOptions | null;
  spinSpeed: number;
  rotation: number;
  dragRef: React.MutableRefObject<DragState>;
  nametag?: SkinRendererNametag | null;
}) {
  const spinRef = useRef<THREE.Group>(null);
  const pitchRef = useRef<THREE.Group>(null);

  const steve = useMemo(() => createSteveRig(variant), [variant]);

  useEffect(() => {
    return () => steve.dispose();
  }, [steve]);

  useFrame((state) => {
    if (spinRef.current) {
      spinRef.current.rotation.y =
        (spinSpeed !== 0
          ? state.clock.elapsedTime * spinSpeed
          : POSE_ROTATION_Y + rotation) + dragRef.current.yaw;
    }
    if (pitchRef.current) {
      pitchRef.current.rotation.x = dragRef.current.pitch;
    }
  });

  return (
    <group
      scale={STEVE_WORLD_SCALE}
      position={[
        0,
        -STEVE_CENTER_PX * STEVE_WORLD_SCALE - (nametag ? DOWN_SHIFT : 0),
        0,
      ]}
    >
      <group ref={pitchRef} position={[0, STEVE_CENTER_PX, 0]}>
      <group position={[0, -STEVE_CENTER_PX, 0]}>
      <group ref={spinRef} rotation={[0, POSE_ROTATION_Y, 0]}>
        <SteveBody
          steve={steve}
          textureUrl={textureUrl}
          emoteUrls={emote}
          emoteLoop={emoteLoop}
          onEmoteEnd={onEmoteEnd}
          emoteSounds={emoteSounds}
        />
        {cosmetics.map((c) =>
          c.type?.toUpperCase() === "OVERLAY" ? (
            <OverlayCosmetic
              key={c.id}
              id={c.id}
              urls={c.urls}
              variant={variant}
            />
          ) : (
            <MountedCosmetic
              key={c.id}
              cosmetic={c}
              anchorRef={spinRef}
              steve={steve}
              variant={variant}
            />
          )
        )}
        {nametag && (
          <Nametag
            tag={nametag}
            y={
              cosmetics.some((c) => c.type?.toUpperCase() === "HAT")
                ? NAMETAG_PX_Y + NAMETAG_HAT_EXTRA_Y
                : NAMETAG_PX_Y
            }
          />
        )}
      </group>
      </group>
      </group>
    </group>
  );
}

function makeShimmerMaterial(color: THREE.Color): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uRes: { value: new THREE.Vector2(1, 1) },
      uColor: { value: color.clone() },
      uOpacity: { value: 1 },
    },
    vertexShader: `
      void main() {
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec2 uRes;
      uniform vec3 uColor;
      uniform float uOpacity;
      void main() {
        vec2 p = gl_FragCoord.xy / uRes;
        float diag = (p.x + p.y) * 0.5;
        float sweep = fract(uTime * 1.2) * 2.0 - 0.5;
        float band = smoothstep(0.22, 0.0, abs(diag - sweep));
        vec3 base = uColor * 0.18;
        vec3 hi = uColor;
        gl_FragColor = vec4(mix(base, hi, band), uOpacity);
      }
    `,
    side: THREE.DoubleSide,
    transparent: true,
    depthTest: false,
    depthWrite: false,
  });
}

function SkeletonContent({
  variant,
  dragRef,
  hasName,
  color,
  fadeOut,
  rotation,
}: {
  variant: SteveModelVariant;
  dragRef: React.MutableRefObject<DragState>;
  hasName: boolean;
  rotation: number;
  color?: string;
  fadeOut: boolean;
}) {
  const spinRef = useRef<THREE.Group>(null);
  const dbSize = useRef(new THREE.Vector2());
  const fadeStart = useRef<number | null>(null);

  const { steve, nametag, material } = useMemo(() => {
    const c = new THREE.Color().setStyle(color || DEFAULT_SKELETON_COLOR);
    const mat = makeShimmerMaterial(c);
    const tree = buildBoneTree(steveGeoForVariant(variant), mat, {
      armorOnly: false,
    });
    tree.root.traverse((o) => {
      o.renderOrder = 998;
    });
    const tag = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), mat);
    tag.rotation.y = Math.PI;
    tag.layers.set(NAMETAG_LAYER);
    tag.scale.set(22, 5, 1);
    tag.renderOrder = 999;
    return { steve: { tree }, nametag: { mesh: tag }, material: mat };
  }, [variant, color]);

  useEffect(() => {
    return () => {
      steve.tree.root.traverse((o) => {
        if (o instanceof THREE.Mesh) o.geometry.dispose();
      });
      nametag.mesh.geometry.dispose();
      material.dispose();
    };
  }, [steve, nametag, material]);

  useFrame((st) => {
    const t = st.clock.elapsedTime;
    st.gl.getDrawingBufferSize(dbSize.current);
    material.uniforms.uTime.value = t;
    material.uniforms.uRes.value.copy(dbSize.current);
    if (fadeOut) {
      if (fadeStart.current === null) fadeStart.current = t;
      material.uniforms.uOpacity.value = Math.max(
        0,
        1 - (t - fadeStart.current) / SKELETON_FADE_S
      );
    }
    if (spinRef.current) {
      spinRef.current.rotation.y =
        POSE_ROTATION_Y + rotation + dragRef.current.yaw;
    }
  });

  return (
    <group
      scale={STEVE_WORLD_SCALE}
      position={[
        0,
        -STEVE_CENTER_PX * STEVE_WORLD_SCALE - (hasName ? DOWN_SHIFT : 0),
        0,
      ]}
    >
      <group ref={spinRef} rotation={[0, POSE_ROTATION_Y, 0]}>
        <primitive object={steve.tree.root} />
        {hasName && (
          <primitive object={nametag.mesh} position={[0, NAMETAG_PX_Y, 0]} />
        )}
      </group>
    </group>
  );
}

function PromoOutline(config: Partial<PromoOutlineConfig>) {
  const gl = useThree((s) => s.gl);
  const scene = useThree((s) => s.scene);
  const camera = useThree((s) => s.camera);
  const size = useThree((s) => s.size);

  const pipeline = useMemo(
    () =>
      setupOutlinePipeline(
        gl,
        scene,
        camera as THREE.PerspectiveCamera,
        size.width,
        size.height
      ),
    [gl, scene, camera]
  );

  useEffect(() => {
    applyOutlineConfig(pipeline, config);
  }, [pipeline, config.strength, config.thickness, config.sensitivity]);

  useEffect(() => {
    resizeOutlinePipeline(pipeline, size.width, size.height);
  }, [pipeline, size.width, size.height]);

  useEffect(() => {
    return () => {
      pipeline.depthRT.dispose();
      pipeline.composer.dispose();
    };
  }, [pipeline]);

  useFrame(() => {
    renderOutlineFrame(pipeline, gl, scene, camera, NAMETAG_LAYER);
  }, 1);

  return null;
}

function FpsLimiter({ fps }: { fps: number }) {
  const invalidate = useThree((s) => s.invalidate);
  useEffect(() => {
    if (!fps || fps <= 0) return;
    let raf = 0;
    let last = 0;
    const interval = 1000 / fps;
    const loop = (t: number) => {
      raf = requestAnimationFrame(loop);
      if (t - last >= interval) {
        last = t;
        invalidate();
      }
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [fps, invalidate]);
  return null;
}

/**
 * Hands [invalidate] to the drag surface, which sits outside the canvas and has no other way to ask
 * for a frame. Needed while paused: the fps limiter is unmounted and the clock stopped, so nothing
 * else would draw the rotation.
 */
function InvalidateBridge({
  invalidateRef,
}: {
  invalidateRef: React.MutableRefObject<(() => void) | null>
}) {
  const invalidate = useThree((s) => s.invalidate);
  useEffect(() => {
    invalidateRef.current = invalidate;
    return () => {
      invalidateRef.current = null;
    };
  }, [invalidate, invalidateRef]);
  return null;
}

function CameraZoom({ zoom }: { zoom: number }) {
  const camera = useThree((s) => s.camera);
  const invalidate = useThree((s) => s.invalidate);

  useEffect(() => {
    camera.position.z = CAMERA_POSITION[2] / (zoom > 0 ? zoom : 1);
    camera.updateProjectionMatrix();
    invalidate();
  }, [camera, invalidate, zoom]);

  return null;
}

function PauseController({ paused }: { paused: boolean }) {
  const clock = useThree((s) => s.clock);
  const invalidate = useThree((s) => s.invalidate);
  useEffect(() => {
    if (paused) {
      clock.autoStart = false;
      clock.stop();
      invalidate();
    } else {
      clock.autoStart = true;
      if (!clock.running) {
        clock.oldTime =
          typeof performance !== "undefined" ? performance.now() : Date.now();
        clock.running = true;
      }
    }
  }, [paused, clock, invalidate]);
  return null;
}

function useSkinVariant(
  textureUrl: string | null,
  requested: SteveModelVariant | "auto",
): SteveModelVariant {
  const [detected, setDetected] = useState<SteveModelVariant>("classic");

  useEffect(() => {
    if (requested !== "auto" || !textureUrl) return;
    let alive = true;
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.onload = () => {
      if (alive) setDetected(inferModelVariant(image));
    };
    image.src = textureUrl;
    return () => {
      alive = false;
    };
  }, [textureUrl, requested]);

  return requested === "auto" ? detected : requested;
}

export function SkinRenderer({
  textureUrl,
  variant = "auto",
  cosmetics = [],
  cape = null,
  emote = null,
  emoteLoop,
  onEmoteEnd,
  emoteSounds = null,
  nametag = null,
  outline = true,
  spinSpeed = 0,
  rotation = 0,
  zoom = 1,
  draggable = true,
  dragAxis = "both",
  loading = false,
  paused = false,
  fps = null,
  maxDpr = 2,
  dpr,
  skeletonColor,
  className,
  style,
  unsupportedFallback,
  onUnsupported,
}: SkinRendererProps) {
  const resolvedVariant = useSkinVariant(textureUrl, variant);
  const withCape = useMemo(() => {
    if (!cape) return cosmetics;
    const asset = typeof cape === "string" ? { texture: cape } : cape;
    const type = asset.elytra ? "ELYTRA" : "CAPE";
    return [
      ...cosmetics,
      {
        id: type.toLowerCase(),
        type,
        urls: {
          geo: "",
          texture: asset.texture,
          mcmeta: asset.mcmeta,
          mcmetaJson: asset.mcmetaJson,
          metadataJson: { type },
        },
      },
    ];
  }, [cape, cosmetics]);
  const dragRef = useRef<DragState>({ yaw: 0, pitch: 0 });
  const invalidateRef = useRef<(() => void) | null>(null);
  const dragging = useRef(false);
  const startX = useRef(0);
  const startY = useRef(0);
  const startDrag = useRef<DragState>({ yaw: 0, pitch: 0 });

  const [skeletonMounted, setSkeletonMounted] = useState(true);
  useEffect(() => {
    if (loading) {
      setSkeletonMounted(true);
      return;
    }
    const id = setTimeout(
      () => setSkeletonMounted(false),
      SKELETON_FADE_S * 1000 + 60
    );
    return () => clearTimeout(id);
  }, [loading]);

  const onPointerDown = (e: React.PointerEvent) => {
    e.preventDefault();
    dragging.current = true;
    startX.current = e.clientX;
    startY.current = e.clientY;
    startDrag.current = { ...dragRef.current };
    e.currentTarget.setPointerCapture(e.pointerId);
  };
  const onPointerMove = (e: React.PointerEvent) => {
    if (!dragging.current) return;
    const pitch =
      dragAxis === "yaw"
        ? 0
        : startDrag.current.pitch +
          (e.clientY - startY.current) * DRAG_SENSITIVITY;
    dragRef.current = {
      yaw:
        startDrag.current.yaw +
        (e.clientX - startX.current) * DRAG_SENSITIVITY,
      pitch: Math.max(-MAX_PITCH, Math.min(MAX_PITCH, pitch)),
    };
    // While paused nothing else asks for a frame - the fps limiter is unmounted and the clock is
    // stopped - so without this the rig would only turn once playback resumed.
    invalidateRef.current?.();
  };
  const endDrag = (e: React.PointerEvent) => {
    dragging.current = false;
    try {
      e.currentTarget.releasePointerCapture(e.pointerId);
    } catch {
      void 0;
    }
  };

  const probed = getWebGLSupport();
  const [contextLost, setContextLost] = useState<WebGLSupport | null>(null);
  const webgl = contextLost ?? probed;

  useEffect(() => {
    if (!webgl.available) onUnsupported?.(webgl);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [webgl.available]);

  const watchContextLoss = ({ gl }: { gl: THREE.WebGLRenderer }) => {
    gl.domElement.addEventListener(
      "webglcontextlost",
      () => setContextLost({ available: false, version: null, reason: "context lost" }),
      { once: true },
    );
  };

  if (!webgl.available) {
    return (
      <div
        className={className}
        style={{ ...style, position: style?.position ?? "relative" }}
      >
        {unsupportedFallback !== undefined ? (
          unsupportedFallback
        ) : (
          <FlatSkin textureUrl={textureUrl} variant={resolvedVariant} />
        )}
      </div>
    );
  }

  return (
    <div
      className={className}
      style={{ ...style, position: style?.position ?? "relative" }}
    >
      <Canvas
        style={{ width: "100%", height: "100%", pointerEvents: "none" }}
        frameloop={fps ? "demand" : "always"}
        dpr={dpr ?? [1, maxDpr]}
        gl={{
          ...RIG_CONTEXT_ATTRIBUTES,
          ...RIG_RENDERER_SETTINGS,
        }}
        camera={{ position: [...CAMERA_POSITION], fov: CAMERA_FOV }}
        onCreated={watchContextLoss}
      >
        <PauseController paused={paused} />
        <CameraZoom zoom={zoom} />
        <InvalidateBridge invalidateRef={invalidateRef} />
        {!paused && fps ? <FpsLimiter fps={fps} /> : null}
        <ambientLight intensity={LIGHTING.ambient} />
        <hemisphereLight intensity={LIGHTING.hemisphere} />
        <directionalLight
          position={[...LIGHTING.directionalPosition]}
          intensity={LIGHTING.directional}
        />
        {!loading && (
          <RigContent
            textureUrl={textureUrl}
            variant={resolvedVariant}
            cosmetics={withCape}
            emote={emote}
            emoteLoop={emoteLoop}
            onEmoteEnd={onEmoteEnd}
            spinSpeed={spinSpeed}
            rotation={rotation}
            dragRef={dragRef}
            nametag={nametag}
          emoteSounds={emoteSounds}
          />
        )}
        {skeletonMounted && (
          <SkeletonContent
            variant={resolvedVariant}
            dragRef={dragRef}
            hasName={!!nametag}
            rotation={rotation}
            color={skeletonColor}
            fadeOut={!loading}
          />
        )}
        {outline !== false && (
          <PromoOutline {...(typeof outline === "object" ? outline : {})} />
        )}
      </Canvas>
      {draggable && (
        <div
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={endDrag}
          onPointerCancel={endDrag}
          onDragStart={(e) => e.preventDefault()}
          draggable={false}
          style={{
            position: "absolute",
            inset: 0,
            cursor: "grab",
            pointerEvents: "auto",
            touchAction: "none",
            userSelect: "none",
            WebkitUserSelect: "none",
          }}
        />
      )}
    </div>
  );
}

function isAttachedTo(node: THREE.Object3D, root: THREE.Object3D): boolean {
  for (let n: THREE.Object3D | null = node; n; n = n.parent) {
    if (n === root) return true;
  }
  return false;
}
